wrong_code.class:
// Only a public constructor is available — callers can't tell what
// "true" or "false" means without checking the parameter list, and
// every call creates a brand-new object even for common values.
public class Connection {
    private final boolean secure;
    public Connection(boolean secure) {
        this.secure = secure;
    }
}

wrong_code.call_site:
public class Main {
    public static void main(String[] args) {
        Connection c = new Connection(true);
        Connection c2 = new Connection(true); // new object, even though
                                               // identical to c
    }
}

right_code.class:
public class Connection {
    private static final Connection SECURE = new Connection(true);
    private static final Connection INSECURE = new Connection(false);

    private final boolean secure;
    private Connection(boolean secure) {
        this.secure = secure;
    }

    public static Connection secure() { return SECURE; }
    public static Connection insecure() { return INSECURE; }
}

right_code.call_site:
public class Main {
    public static void main(String[] args) {
        Connection c = Connection.secure();
        Connection c2 = Connection.secure(); // same cached instance
        System.out.println(c == c2); // true
    }
}
